def solve(inputs: dict) -> float:
    terms = inputs.get('terms', inputs.get('continued_fraction_terms', inputs.get('a')))
    if terms is None:
        for v in inputs.values():
            if isinstance(v, (list, tuple)):
                terms = v
                break
    p_prev, p = 0, 1
    for a in terms:
        p_prev, p = p, int(a) * p + p_prev
    return p

