def solve(inputs: dict) -> float:
    n = inputs.get('n', inputs.get('people', inputs.get('count')))
    k = inputs.get('k', inputs.get('step', inputs.get('every')))
    if n is None or k is None:
        vals = [v for v in inputs.values() if isinstance(v, int)]
        if n is None and vals:
            n = vals[0]
        if k is None and len(vals) > 1:
            k = vals[1]
    survivor = 0
    for size in range(2, int(n) + 1):
        survivor = (survivor + int(k)) % size
    return survivor + 1

